SELECT order_cohort, total_count, channel_list FROM (SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, COUNT(*) AS total_count, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list FROM orders WHERE store_id IN (26, 28, 36, 38) GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS t WHERE total_count < 4 ORDER BY total_count DESC;
